<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Documents {
    public static function access(\PDO $p,int $actor,int $id,bool $manage=false):array {
        $d=Database::query($p,'SELECT * FROM documents WHERE id=?',[$id])->fetch();if(!$d)throw new \InvalidArgumentException('Dokumen tidak wujud.');Core::module($p,$d['module_code']);$org=(int)$d['organisation_id'];if($d['module_code']==='eforms'){foreach(['Schema','Service'] as $class)require_once APP_ROOT.'/app/Modules/EForms/'.$class.'.php';\EPejabat\Modules\EForms\Service::documentAccess($p,$actor,$d,$manage);return $d;}if($d['module_code']==='training'){\EPejabat\Modules\Training\TrainingDocuments::access($p,$actor,$d,$manage);return $d;}if(!$manage&&$d['module_code']==='core'&&RegistrationMaster::profileReady($p)&&in_array($d['status'],['active','locked'],true)&&Authorization::allowed($p,$actor,'core.staff.professional.verify',$org)&&Database::query($p,"SELECT 1 FROM staff_profile_reviews r JOIN staff_profiles s ON s.staff_identity_id=r.staff_identity_id WHERE r.evidence_document_id=? AND r.organisation_id=? AND r.organisation_id=s.organisation_id AND r.requested_by=? AND r.status IN ('PENDING_VERIFICATION','VERIFIED','REJECTED')",[$id,$org,$d['owner_id']])->fetchColumn())return $d;$perm=$d['module_code'].'.documents.'.($manage?'manage':'view');Authorization::require($p,$actor,$perm,$org);if(!Authorization::allowed($p,$actor,$d['module_code'].'.documents.manage',$org)&&(int)$d['owner_id']!==$actor)throw new \RuntimeException('Akses tidak dibenarkan.');return $d;
    }
    public static function upload(\PDO $p,int $actor,int $org,string $module,string $title,array $file,?int $doc=null,?int $programme=null):int {
        Core::module($p,$module);if($module==='training')$programme=\EPejabat\Modules\Training\TrainingDocuments::upload($p,$actor,$org,$programme,$doc);elseif($module==='eforms'){foreach(['Schema','Service'] as $class)require_once APP_ROOT.'/app/Modules/EForms/'.$class.'.php';if(!$programme)throw new \RuntimeException('Submission e-Forms diperlukan.');$s=\EPejabat\Modules\EForms\Service::get($p,$actor,$programme);if((int)$s['applicant_id']!==$actor||!in_array($s['status'],['draft','returned'],true)||(int)$s['organisation_id']!==$org)throw new \RuntimeException('Upload e-Forms tidak dibenarkan.');\EPejabat\Modules\EForms\Service::permit($p,$actor,'documents.upload',$org);}else Authorization::require($p,$actor,$module.'.documents.upload',$org);$title=Core::text($title);if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']??''))throw new \InvalidArgumentException('Upload gagal.');$tmp=$file['tmp_name'];$size=filesize($tmp);if($size<1||$size>5*1024*1024)throw new \InvalidArgumentException('Fail maksimum 5 MB.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($allowed[$mime]))throw new \InvalidArgumentException('PDF, JPEG atau PNG sahaja.');$name=Core::text(basename($file['name']),190);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,['pdf','jpg','jpeg','png'],true)||($mime==='application/pdf'&&$ext!=='pdf')||($mime==='image/png'&&$ext!=='png')||($mime==='image/jpeg'&&!in_array($ext,['jpg','jpeg'],true)))throw new \InvalidArgumentException('Extension tidak sepadan.');
        if($mime==='application/pdf'){if(strncmp(file_get_contents($tmp,false,null,0,5),'%PDF-',5)!==0)throw new \InvalidArgumentException('PDF tidak sah.');}else{$i=@getimagesize($tmp);if(!$i||$i[0]*$i[1]>40000000||$i['mime']!==$mime)throw new \InvalidArgumentException('Imej tidak sah atau terlalu besar.');}
        $key=bin2hex(random_bytes(32));$target=APP_ROOT.'/storage/documents/'.$key;if(!move_uploaded_file($tmp,$target)||!chmod($target,0600))throw new \RuntimeException('Storan tidak tersedia.');try{return Core::tx($p,function()use($p,$actor,$org,$module,$title,$doc,$key,$name,$mime,$size,$target,$programme){if($doc){$d=self::access($p,$actor,$doc);Database::query($p,'SELECT id FROM documents WHERE id=? FOR UPDATE',[$doc]);if($d['status']!=='active'||$d['organisation_id']!=$org||$d['module_code']!==$module)throw new \RuntimeException('Dokumen dikunci atau scope berubah.');}else{Database::query($p,'INSERT INTO documents(owner_id,organisation_id,module_code,title) VALUES(?,?,?,?)',[$actor,$org,$module,$title]);$doc=(int)$p->lastInsertId();if($module==='training')Database::query($p,'INSERT INTO training_programme_documents(programme_id,document_id,purpose) VALUES(?,?,?)',[$programme,$doc,'programme_attachment']);}$version=(int)Database::query($p,'SELECT COALESCE(MAX(version),0)+1 FROM document_versions WHERE document_id=?',[$doc])->fetchColumn();Database::query($p,'INSERT INTO document_versions(document_id,version,storage_key,original_name,mime,byte_size,checksum,uploaded_by) VALUES(?,?,?,?,?,?,?,?)',[$doc,$version,$key,$name,$mime,$size,hash_file('sha256',$target),$actor]);Audit::record($p,'document.uploaded',$actor,$org,(string)$doc,$module,null,null,['version'=>$version,'mime'=>$mime,'byte_size'=>$size]);return $doc;});}catch(\Throwable $e){@unlink($target);throw $e;}
    }
    public static function version(\PDO $p,int $actor,int $doc,int $version):array {$d=self::access($p,$actor,$doc);$v=Database::query($p,'SELECT * FROM document_versions WHERE document_id=? AND version=?',[$doc,$version])->fetch();if(!$v||!preg_match('/\A[a-f0-9]{64}\z/',$v['storage_key']))throw new \InvalidArgumentException('Versi tidak wujud.');$path=APP_ROOT.'/storage/documents/'.$v['storage_key'];if(!is_file($path)||!hash_equals($v['checksum'],hash_file('sha256',$path)))throw new \RuntimeException('Integriti fail gagal.');Audit::record($p,'document.downloaded',$actor,(int)$d['organisation_id'],(string)$doc,$d['module_code']);return [...$v,'path'=>$path];}
    public static function status(\PDO $p,int $actor,int $doc,string $status,string $reason):void {if(!in_array($status,['active','locked','archived'],true))throw new \InvalidArgumentException('Status tidak sah.');Core::tx($p,function()use($p,$actor,$doc,$status,$reason){$d=self::access($p,$actor,$doc,true);if($d['module_code']==='training'&&\EPejabat\Modules\Training\ExtendedMigrations::ready($p)&&Database::query($p,'SELECT 1 FROM training_outputs WHERE document_id=?',[$doc])->fetchColumn())throw new \RuntimeException('Official document status immutable.');Database::query($p,'UPDATE documents SET status=? WHERE id=?',[$status,$doc]);Audit::record($p,'document.status_changed',$actor,(int)$d['organisation_id'],(string)$doc,$d['module_code'],Core::text($reason,500),['status'=>$d['status']],['status'=>$status]);});}
}
